// Contrôles simples, sans IA : adresse, SIREN (clé de Luhn), consentement à l'information RGPD.
const f = $('Demande de contact').first().json;
const email = String(f.email ?? '').trim().toLowerCase();
if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email)) throw new Error('Adresse email invalide : ' + email);
const PERSO = ['gmail.com', 'yahoo.fr', 'yahoo.com', 'hotmail.com', 'hotmail.fr', 'outlook.com', 'outlook.fr', 'live.fr', 'orange.fr', 'free.fr', 'sfr.fr', 'laposte.net', 'wanadoo.fr', 'icloud.com', 'gmx.fr'];
const siren = String(f.siren ?? '').replace(/\D/g, '');
const luhn = s => { let t = 0; for (let i = 0; i < s.length; i++) { let n = +s[s.length - 1 - i]; if (i % 2) { n *= 2; if (n > 9) n -= 9; } t += n; } return t % 10 === 0; };
const consentement = [].concat(f.rgpd ?? []).length > 0;
if (!consentement) throw new Error('Information RGPD non acceptée : la demande ne peut pas être traitée.');
const code_postal = String(f.code_postal ?? '').trim();
if (!/^\d{5}$/.test(code_postal)) throw new Error('Code postal invalide : ' + code_postal);
const pro = f.type === 'Professionnel';
return [{ json: { nom: String(f.nom ?? '').trim(), email, type: pro ? 'professionnel' : 'particulier', entreprise: pro ? String(f.entreprise ?? '').trim() : '', code_postal,
  siren: pro && siren.length === 9 && luhn(siren) ? siren : '', siren_saisi: pro ? siren : '', budget: f.budget, delai: f.delai, besoin: String(f.besoin ?? '').trim(),
  adresse_perso: pro && PERSO.includes(email.split('@')[1]) } }];

// Fiche entreprise du registre public : uniquement des données sur l'entreprise (jamais les dirigeants).
const d = $('Normaliser').first().json;
const reg = $('Réglages').first().json;
const res = d.type === 'professionnel' ? ($('Registre des entreprises').first().json.results ?? []) : [];
const TRANCHES = { NN: 'non renseigné', '00': '0 salarié', '01': '1 ou 2', '02': '3 à 5', '03': '6 à 9', '11': '10 à 19', '12': '20 à 49', '21': '50 à 99', '22': '100 à 199', '31': '200 à 249', '32': '250 à 499', '41': '500 à 999', '42': '1 000 à 1 999', '51': '2 000 à 4 999', '52': '5 000 à 9 999', '53': '10 000 et plus' };
const norm = s => String(s ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
let r = null;
if (d.siren) r = res.find(x => x.siren === d.siren) ?? null;
else if (d.entreprise) r = res.find(x => (!d.code_postal || x.siege?.code_postal === d.code_postal) && (norm(x.nom_complet).includes(norm(d.entreprise)) || norm(d.entreprise).includes(norm(x.nom_raison_sociale)))) ?? null;
const fiche = r ? { trouvee: true, siren: r.siren, nom: r.nom_complet, naf: r.activite_principale, categorie: r.categorie_entreprise,
  effectif: TRANCHES[r.tranche_effectif_salarie] ?? 'non renseigné', commune: r.siege?.libelle_commune ?? '', active: r.etat_administratif === 'A', creation: r.date_creation }
  : { trouvee: false };
const registre = d.type !== 'professionnel' ? 'particulier' : !fiche.trouvee ? 'introuvable' : fiche.active ? 'vérifiée, active' : 'trouvée, mais cessée';
// Distance à vol d'oiseau entre l'atelier et la commune du chantier (centre de la commune, API géographique publique)
const commune = ($('Commune du chantier').first().json.body ?? $('Commune du chantier').all().map(i => i.json))[0] ?? $('Commune du chantier').first().json;
const c = commune?.centre?.coordinates;
const rad = x => x * Math.PI / 180;
const km = c ? Math.round(2 * 6371 * Math.asin(Math.sqrt(Math.sin(rad(c[1] - reg.atelier.lat) / 2) ** 2 + Math.cos(rad(reg.atelier.lat)) * Math.cos(rad(c[1])) * Math.sin(rad(c[0] - reg.atelier.lon) / 2) ** 2))) : null;
return [{ json: { ...d, fiche, registre, commune: commune?.nom ?? 'inconnue', distance_km: km } }];

// Score final : la note de l'IA (besoin) + des points fixes et vérifiables (budget, délai, taille, registre).
const d = $('Fiche entreprise').first().json;
const ia = $('Qualifier le besoin').first().json.output;
const reg = $('Réglages').first().json;
const BUDGET = { 'Moins de 2 000 €': 6, 'De 2 000 à 10 000 €': 15, 'De 10 000 à 30 000 €': 20, 'Plus de 30 000 €': 20, 'Je ne sais pas encore': 8 };
const DELAI = { 'Moins d\'un mois': 15, 'De 1 à 3 mois': 12, 'Plus tard': 5 };
const FIABILITE = { 'particulier': 7, 'vérifiée, active': 10, 'introuvable': 4, 'trouvée, mais cessée': 0 };
const dk = d.distance_km;
const zone = dk == null ? 6 : dk <= reg.zone_km ? 15 : dk <= reg.zone_km * 1.5 ? 6 : 0;
const detail = [
  ['Besoin (IA)', Math.max(0, Math.min(40, Math.round(ia.adequation))), 40, ia.justification],
  ['Budget', BUDGET[d.budget] ?? 8, 20, d.budget],
  ['Délai', DELAI[d.delai] ?? 5, 15, d.delai],
  ['Zone', zone, 15, dk == null ? 'commune inconnue' : d.commune + ' · ' + dk + ' km de l\'atelier'],
  ['Fiabilité', FIABILITE[d.registre] ?? 4, 10, d.registre + (d.fiche.trouvee ? ' · ' + d.fiche.nom : '')],
].map(([critere, points, max, motif]) => ({ critere, points, max, motif }));
let score = detail.reduce((s, x) => s + x.points, 0);
const alertes = [];
if (d.adresse_perso) { score -= 5; alertes.push('adresse email personnelle'); }
if (d.siren_saisi && !d.siren) alertes.push('SIREN saisi invalide');
if (d.registre === 'trouvée, mais cessée') alertes.push('entreprise cessée au registre');
const horsZone = dk != null && dk > reg.zone_km * 1.5;
if (horsZone) alertes.push('hors zone : ' + dk + ' km (zone de ' + reg.zone_km + ' km)');
score = Math.max(0, Math.min(100, score));
const categorie = ia.spam ? 'écarté' : horsZone ? 'hors zone' : score >= 70 ? 'chaud' : score >= 40 ? 'tiède' : 'froid';

// Dédoublonnage : même adresse = même prospect, on met à jour sa fiche.
const ancien = $('Déjà dans le CRM ?').all().map(i => i.json).find(r => r && r.email === d.email);
const maintenant = $now.setZone('Europe/Paris');
return [{ json: { ...d, score, categorie, detail, alertes, resume: ia.resume, questions: ia.questions ?? [], reponse: ia.reponse,
  nb_demandes: (ancien?.nb_demandes ?? 0) + 1, premiere_demande: ancien?.premiere_demande ?? maintenant.toISO(),
  dernier_contact: maintenant.toISO(), conservation_jusqua: maintenant.plus({ years: 3 }).toISODate(), deja_connu: !!ancien } }];

// Par défaut : purge réelle à la date du jour (déclenchement de nuit).
const f = $('Purge à la demande').isExecuted ? $('Purge à la demande').first().json : {};
const simulation = String(f.mode ?? '').startsWith('Simulation');
const autoriseDate = simulation || true;
const reference = autoriseDate && f.date ? f.date : $now.setZone('Europe/Paris').toISODate();
return [{ json: { simulation, reference } }];

const p = $('Paramètres de la purge').first().json;
const echues = $('Fiches arrivées à échéance').all().map(i => i.json).filter(r => r && r.email);
return [{ json: { ...p, nombre: echues.length, fiches: echues.map(r => ({ email: r.email, entreprise: r.entreprise, jusqua: DateTime.fromISO(String(r.conservation_jusqua)).setZone('Europe/Paris').toISODate() })) } }];
